extends SceneTree

func _init():
    var timer = Timer.new()
    timer.wait_time = 2.0
    timer.one_shot = true
    root.add_child(timer)

    # 1. Test invalid load
    var res = SceneLoader.start_load("res://does/not/exist.tscn")
    if res != false: # Wait, start_load("does/not/exist.tscn")
        # ResourceLoader.exists will be false, so it returns false.
        pass

    # Actually, the test is:
    # Calling start_load("res://does/not/exist.tscn") must cause load_failed to fire within 1 second.
    # We need to set up a listener.

    SceneLoader.load_failed.connect(_on_failed_invalid)
    SceneLoader.start_load("res://does/not/exist.tscn")

    # 2. Test valid load
    SceneLoader.load_completed.connect(_on_completed_valid)
    SceneLoader.start_load("res://scenes/HugeLevel.tscn")

    # Add a timer to quit
    timer.start()
    timer.timeout.connect(self.quit)

func _on_failed_invalid(reason):
    print("Invalid path failed correctly: " + reason)

func _on_completed_valid(scene):
    print("Valid path loaded correctly")
    var node = scene.instantiate()
    var count = _count_node2d(node)
    print("Node2D descendants: " + str(count))
    if count >= 50:
        print("ALL TESTS PASSED")
    else:
        print("FAIL: Not enough nodes")
        quit(1)

func _count_node2d(node):
    var count = 0
    if node is Node2D:
        count = 1
    for child in node.get_children():
        count += _count_node2d(child)
    return count
